Next, you can create two functions to return the top three coins with the highest average profit and the top three coins with the highest average loss. Here's the implementation:

```dart
class Transaction {
  final String coinName;
  final DateTime datetime;
  final int profitOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitOrLoss});
}

double calculateAverageProfit(List<Transaction> transactions) {
  int totalProfit = 0;
  for (var transaction in transactions) {
    totalProfit += transaction.profitOrLoss;
  }
  double averageProfit = totalProfit / transactions.length;
  return averageProfit;
}

double calculateAverageLoss(List<Transaction> transactions) {
  int totalLoss = 0;
  for (var transaction in transactions) {
    totalLoss += transaction.profitOrLoss * -1;
  }
  double averageLoss = totalLoss / transactions.length;
  return averageLoss;
}

List<String> getTopCoinsWithHighestAverageProfit(List<Transaction> transactions, int numOfCoins) {
  Map<String, List<int>> coinTransactions = {};
  for (var transaction in transactions) {
    if (coinTransactions.containsKey(transaction.coinName)) {
      coinTransactions[transaction.coinName]!.add(transaction.profitOrLoss);
    } else {
      coinTransactions[transaction.coinName] = [transaction.profitOrLoss];
    }
  }

  List<MapEntry<String, double>> avgProfits = [];
  for (var entry in coinTransactions.entries) {
    double avgProfit = calculateAverageProfit(entry.value);
    avgProfits.add(MapEntry(entry.key, avgProfit));
  }

