import com.atlassian.jira.service.impl.JiraServiceContext
import com.googlecode.catchexception.CatchException

@CatchException(IssueValidationException.class)
def validate(issue, draft, context) {
    def checklists = ComponentAccessor.getIssueService().getTransitionChecker(issue).getTransitionsFor(issue).collect { t -> t.getDescription()?.checklist }.flatten()
    def completedChecklists = []

    checklists.each { c ->
        c.items.each { I ->
            if (I.status == 'done') {
                completedChecklists++
            }
        }
    }

    if (completedChecklists != checklists.size()) {
        throw new IssueValidationException("All items in the checklist must be completed before moving this issue.")
    }
}
```

