const carSizes = require('./carSizes.json'); // assume this file contains the JSON data provided

function recommendCarSize(height) {
  let carSize;
  for (let size in carSizes) {
    const heightRange = carSizes[size].heightRange.split(' - ');
    const startHeight = parseFloat(heightRange[0]);
    const endHeight = parseFloat(heightRange[1]);
