Sure! Here's a JavaScript function that switches the order of adjectives:

```js
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Filter out common stop words (you can add or remove as needed)
  const stopWords = ["a", "an", "the"];
  const filteredWords = words.filter((word) => !stopWords.includes(word));

  // Find the first adjective and the second adjective
  let firstAdjectiveIndex = -1;
  let secondAdjectiveIndex = -1;
  for (let i = 0; i < filteredWords.length; i++) {
    if (isAdjective(filteredWords[i])) {
      firstAdjectiveIndex = i;
      break;
    }
  }
  for (let j = firstAdjectiveIndex - 1; j >= 0; j--) {
    if (isAdjective(filteredWords[j])) {
      secondAdjectiveIndex = j;
      break;
    }
  }

  // Swap the positions of the first and second adjectives
  const temp = filteredWords[firstAdjectiveIndex];
  filteredWords[firstAdjectiveIndex] = filteredWords[secondAdjectiveIndex];
  filteredWords[secondAdjectiveIndex] = temp;

  // Join the filtered words back into a sentence
  const result = filteredWords.join(" ");

  // Add back the stop words that were removed earlier
  const finalResult = result.split(" ")
                             .map((word, index) => (stopWords.includes(word)) ? word : filteredWords[index])
                             .join(" ");

  return finalResult;
}

// Helper function to check if a word is an adjective
const isAdjective = (word) => /\b[A-Za-z]{2,}\b/.test(word);
```

