Here's a C++ implementation of bubble sort for your given input:

```cpp
#include <iostream>
#include <nlohmann/json.hpp>
#include <vector>

namespace json = nlohmann;

// Bubble sort function with optimizations
void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped = true; // Flag to know if any elements were swapped

    // Outer loop to set last unsorted element as pivot
    while (swapped) {
        swapped = false; // Reset flag

        // Inner loop to swap adjacent elements if they are in wrong order
        for (int i = 0; i < n - 1; ++i) {
            if (arr[i] > arr[i+1]) { // Swap if current is greater than next
                std::swap(arr[i], arr[i+1]);
                swapped = true; // Set flag if any swaps were made
            }
        }

        // Decrement n since the last element is now in place
        --n;
    }
}

// Function to parse JSON input and call bubbleSort
void sortJSONArray(json& j) {
    auto& arr = j["array"]; // Access "array" member
    bubbleSort(arr); // Call bubbleSort on vector
}

// Example usage:
int main() {
    json input; // Declare JSON object
    std::cout << "Enter JSON input:\n";
    std::cin >> input; // Read JSON input from console

    sortJSONArray(input); // Call sorting function

    std::cout << "Sorted JSON output:\n";
    std::cout << input.dump(2); // Print sorted JSON with indentation

    return 0;
}
```

