        adjustedCarPrice = carPrice;
    }

    // Step 4: Calculate the total cost of the purchase
    decimal totalPurchasePrice = totalClothesAndBooksPrice + adjustedCarPrice;

    // Step 5: Return the total cost of the purchase
    return totalPurchasePrice;
}
