function smart_sort_array($set, $order) {
    usort($set, function($a, $b) use ($order) {
        $ageA = $a['age'];
        $ageB = $b['age'];
        if ($ageA == $ageB) { // If ages are equal, sort by name instead
            return strnatcasecmp($a['name'], $b['name']);
        } else { // Otherwise, sort by age in desired order
            return $order === 'asc' ? $ageA - $ageB : $ageB - $ageA;
        }
    });
    return $set;
}
```

