function findEntriesInOptions(options, keyPath, value) {
  let currentObject = options;
  const keys = keyPath.split(".");

  for (let I = 0; I < keys.length - 1; i++) {
    if (!currentObject[keys[i]]) {
      return []; // Key not found, return empty array
    }
    currentObject = currentObject[keys[i]];
  }

  const lastKey = keys[keys.length - 1];
  const lastObject = {};
  let entries = [];

  for (let prop in currentObject) {
    const nestedValue = currentObject[prop][lastKey];

    if (nestedValue === value) {
      lastObject[prop] = currentObject[prop];

      // Check if this is already present in the entries list
      // If yes, merge objects instead of adding duplicates
      const existingEntryIndex = entries.findIndex(e => e.key === prop);
      if (existingEntryIndex >= 0) {
        Object.assign(entries[existingEntryIndex], lastObject);
      } else {
        entries.push({ key: prop, value: lastObject });
      }
    }
  }

  return entries;
}

// Example usage:
const options = {
  a: { b: { c: "value" }, d: "other_value" } },
  e: { f: { g: "another_value" } } };
const keyPath = "a.b";
const value = "value";
const entries = findEntriesInOptions(options, keyPath, value);
console.log(entries); // Expected output: [{ key: 'c', value: { c: 'value' } }]
```

